WITH sessions_by_customer AS (SELECT customer_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(device))) device_values, COUNT(CASE WHEN browser = 'Edge' THEN 1 END) edge_count FROM sessions WHERE customer_id IS NOT NULL GROUP BY customer_id) SELECT c.id, c.age, sbc.device_values, sbc.edge_count FROM customers c INNER JOIN sessions_by_customer sbc ON c.id = sbc.customer_id WHERE sbc.edge_count >= 5 ORDER BY sbc.edge_count ASC;
